export type BearerToken = string;

// ---------------------------------------------------------------------------
// State machine
// ---------------------------------------------------------------------------

/**
 * Public boot state.
 *
 *   - `idle`                  — the machine has been constructed but hasn't
 *                              run yet.
 *   - `validating`            — `GET /api/session` is in flight.
 *   - `authenticated`         — `/api/session` returned 200, host can
 *                              resume the WS handshake with the token.
 *   - `session-expired`       — token was rejected; the caller must show
 *                              the claims screen with an expired banner.
 *                              The expired callsign is captured so the
 *                              screen can disable it.
 *   - `awaiting-claim`        — no token existed on boot; the caller
 *                              should show the claims screen with no
